def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    seen=set()
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=0 or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); comp=[]
            while stack:
                x,y=stack.pop(); comp.append((x,y))
                for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0<=a<h and 0<=b<w and grid[a][b]==0 and (a,b) not in seen:
                        seen.add((a,b)); stack.append((a,b))
            # Recolor connected zero shapes of size >=2, preserving isolated noise.
            if len(comp)>=2:
                for x,y in comp: out[x][y]=8
    return out
